WITH "golem_contributions" AS MATERIALIZED (SELECT "golem_limited_contributions"."golem_c0" AS "golem_c0", "golem_limited_contributions"."golem_c1" AS "golem_c1", COUNT(*) OVER () AS "golem_contribution_count" FROM (SELECT "golem_a0"."title" AS "golem_c0", "golem_a0"."title" AS "golem_c1" FROM "posts" AS "golem_a0" WHERE TRUE LIMIT ?1) AS "golem_limited_contributions"), "golem_groups" AS MATERIALIZED (SELECT "golem_limited_groups".*, COUNT(*) OVER () AS "golem_intermediate_count" FROM (SELECT ("golem_contributions"."golem_c0" COLLATE BINARY) AS "golem_d0", COUNT(*) AS "golem_m0", MIN(("golem_contributions"."golem_c1" COLLATE BINARY)) AS "golem_o0", MAX("golem_contributions"."golem_contribution_count") AS "golem_contribution_count" FROM "golem_contributions" AS "golem_contributions" GROUP BY ("golem_contributions"."golem_c0" COLLATE BINARY) LIMIT ?2) AS "golem_limited_groups") SELECT "golem_guarded"."golem_d0" AS "golem_d0", "golem_guarded"."golem_m0" AS "golem_m0", "golem_guarded"."golem_contribution_count" AS "golem_contribution_count", "golem_guarded"."golem_intermediate_count" AS "golem_intermediate_count", "golem_guarded"."golem_guard_row" AS "golem_guard_row" FROM (SELECT "golem_visible"."golem_d0" AS "golem_d0", "golem_visible"."golem_m0" AS "golem_m0", "golem_visible"."golem_o0" AS "golem_o0", "golem_visible"."golem_contribution_count" AS "golem_contribution_count", "golem_visible"."golem_intermediate_count" AS "golem_intermediate_count", ROW_NUMBER() OVER (ORDER BY "golem_visible"."golem_o0" IS NOT NULL ASC, ("golem_visible"."golem_o0" COLLATE BINARY) ASC, "golem_visible"."golem_d0" IS NOT NULL ASC, ("golem_visible"."golem_d0" COLLATE BINARY) ASC) AS "golem_page_ordinal", 0 AS "golem_guard_row" FROM (SELECT "golem_grouped"."golem_d0" AS "golem_d0", "golem_grouped"."golem_m0" AS "golem_m0", "golem_grouped"."golem_o0" AS "golem_o0", "golem_grouped"."golem_contribution_count" AS "golem_contribution_count", "golem_grouped"."golem_intermediate_count" AS "golem_intermediate_count" FROM "golem_groups" AS "golem_grouped" ORDER BY "golem_grouped"."golem_o0" IS NOT NULL ASC, ("golem_grouped"."golem_o0" COLLATE BINARY) ASC, "golem_grouped"."golem_d0" IS NOT NULL ASC, ("golem_grouped"."golem_d0" COLLATE BINARY) ASC LIMIT ?3) AS "golem_visible" UNION ALL SELECT NULL AS "golem_d0", NULL AS "golem_m0", NULL AS "golem_o0", COALESCE(MAX("golem_guard_groups"."golem_contribution_count"), 0) AS "golem_contribution_count", COALESCE(MAX("golem_guard_groups"."golem_intermediate_count"), 0) AS "golem_intermediate_count", 0 AS "golem_page_ordinal", 1 AS "golem_guard_row" FROM "golem_groups" AS "golem_guard_groups") AS "golem_guarded" ORDER BY "golem_guarded"."golem_guard_row" ASC, "golem_guarded"."golem_page_ordinal" ASC